css:
:root{
  --porcelain:#FFF9F3; --apricot:#E7A17F; --apricot-d:#D08761; --peach:#F2C5B2;
  --peach-l:#FBEDE5; --gold:#C2A05C; --ink:#3D303B; --ink-d:#2C222B; --oyster:#DDD4CC;
  --muted:#7A6E76; --line:#EADFD6; --white:#FFFFFF;
  --gut:44px; --r:2px;
  --shadow:0 1px 2px rgba(61,48,59,.04), 0 12px 32px rgba(61,48,59,.07);
  --shadow-lg:0 2px 6px rgba(61,48,59,.05), 0 28px 66px rgba(61,48,59,.12);
  --serif:"Cormorant Garamond",Georgia,"Times New Roman",serif;
  --sans:Montserrat,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font-family:var(--sans);
  font-size:16px;line-height:1.75;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--serif);font-weight:400;line-height:1.16;letter-spacing:0;margin:0}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul,ol{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:1300px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:104px;padding-bottom:104px}
.sec-t{padding-top:74px;padding-bottom:74px}
.eyebrow{font-family:var(--sans);font-weight:500;font-size:11px;letter-spacing:.24em;
  text-transform:uppercase;color:var(--muted);margin-bottom:18px}
.h2{font-size:clamp(31px,4.1vw,50px)}
.lead{color:var(--muted);font-size:16.5px;max-width:60ch;line-height:1.85}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.sec-head{margin-bottom:48px}
em.acc{font-style:italic;color:var(--apricot-d)}
.gold-rule{width:46px;height:1px;background:var(--gold);margin:0 0 22px}
.ctr .gold-rule{margin-left:auto;margin-right:auto}

/* ---------- images ---------- */
.cimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:var(--peach-l)}
.simg{display:block;width:100%;height:auto;aspect-ratio:4/5;object-fit:cover;background:var(--peach-l)}

/* ---------- reveal (pure CSS, JS-free) ---------- */
.rv{animation:rvIn .9s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:.55;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:var(--sans);font-weight:600;font-size:11.5px;letter-spacing:.18em;text-transform:uppercase;
  padding:18px 36px;border-radius:var(--r);border:1px solid transparent;cursor:pointer;
  transition:background .22s ease,color .22s ease,border-color .22s ease;white-space:nowrap}
.btn-1{background:var(--apricot);color:var(--ink)}
.btn-1:hover{background:var(--apricot-d);color:#fff}
.btn-2{background:transparent;color:var(--ink);border-color:var(--oyster)}
.btn-2:hover{border-color:var(--apricot);background:var(--peach-l)}
.btn-d{background:var(--ink);color:#fff}
.btn-d:hover{background:var(--ink-d)}
.btn-w{background:#fff;color:var(--ink);border-color:#fff}
.btn-w:hover{background:var(--peach-l)}
.btn-o{background:transparent;color:#fff;border-color:rgba(255,255,255,.48)}
.btn-o:hover{background:rgba(255,255,255,.13);border-color:#fff}
.btn-sm{padding:13px 24px;font-size:10.5px}
.btn-lg{padding:20px 44px;font-size:12px}
.lnk{font-family:var(--sans);font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;
  font-weight:600;color:var(--apricot-d);display:inline-flex;align-items:center;gap:9px}
.lnk::after{content:"";width:20px;height:1px;background:var(--apricot-d);transition:width .22s ease}
a:hover .lnk::after{width:32px}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(255,249,243,.96);
  backdrop-filter:saturate(150%) blur(12px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:24px;min-height:86px}
.brand{flex-shrink:0;font-family:var(--serif);font-size:21px;letter-spacing:.16em;color:var(--ink);
  white-space:nowrap;line-height:1;text-transform:uppercase}
.nav{margin-left:auto;display:flex;align-items:center;gap:2px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:6px;padding:10px 12px;
  font-size:10.8px;letter-spacing:.15em;text-transform:uppercase;font-weight:600;color:var(--ink);
  cursor:pointer;white-space:nowrap;transition:color .2s ease}
.nav a.top:hover,.nav .drop-lbl:hover{color:var(--apricot-d)}
.nav-cta{display:none}
.nav .caret{width:8px;height:8px;flex-shrink:0;opacity:.55}
.menu{position:absolute;top:calc(100% + 16px);left:-10px;min-width:264px;background:var(--white);
  border:1px solid var(--line);box-shadow:var(--shadow-lg);padding:16px 12px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.2s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 14px;font-size:15px;font-family:var(--serif);color:var(--ink);
  transition:.18s ease}
.menu a:hover{background:var(--peach-l);color:var(--apricot-d)}
.menu .mh{display:block;padding:4px 14px 10px;font-size:9.5px;letter-spacing:.22em;
  text-transform:uppercase;color:var(--muted);font-family:var(--sans);font-weight:600}
.hdr-act{display:flex;align-items:center;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- hero ---------- */
.hero{background:var(--peach-l);border-bottom:1px solid var(--line)}
.hero-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.02fr);gap:0;align-items:stretch}
.hero-txt{padding:98px 64px 98px 0;display:flex;flex-direction:column;justify-content:center;min-width:0}
h1{font-size:clamp(36px,4.7vw,58px);margin-bottom:22px;line-height:1.12}
h1 em{font-style:italic;color:var(--apricot-d)}
.hero-lead{font-size:16.5px;color:var(--muted);max-width:48ch;margin-bottom:34px;line-height:1.85}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:34px}
.ticks{display:flex;flex-wrap:wrap;gap:12px 28px}
.tick{display:flex;align-items:center;gap:9px;font-size:12.5px;color:var(--muted);letter-spacing:.03em}
.tick svg{width:15px;height:15px;flex-shrink:0}
.hero-img{position:relative;min-width:0}
.hero-img img{display:block;width:100%;height:100%;min-height:560px;object-fit:cover}
.swap-tag{position:absolute;right:14px;bottom:14px;background:rgba(61,48,59,.62);color:#fff;
  font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;padding:7px 14px;border-radius:var(--r)}

/* ---------- trust strip ---------- */
.strip{background:var(--ink);color:#E8E1E4}
.strip .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;
  padding-top:28px;padding-bottom:28px}
.strip div{min-width:0;display:flex;align-items:center;gap:12px;font-size:12.6px;letter-spacing:.04em}
.strip svg{width:18px;height:18px;flex-shrink:0}

/* ---------- tiles ---------- */
.tiles{display:grid;gap:24px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tile{min-width:0;display:block;background:var(--white);border:1px solid var(--line);
  transition:border-color .25s ease,box-shadow .25s ease}
.tile:hover{border-color:var(--peach);box-shadow:var(--shadow)}
.tile .tb{padding:20px 22px 24px}
.tile b{display:block;font-family:var(--serif);font-weight:400;font-size:21px;margin-bottom:5px}
.tile span{display:block;font-size:13px;color:var(--muted);line-height:1.7}
.tile .lnk{margin-top:14px}
.kwl{margin-top:12px;font-size:11.5px;color:var(--muted);line-height:1.75}
.kwl b{display:inline;font-family:var(--sans);font-size:11.5px;font-weight:600;color:var(--ink)}

/* ---------- dark quote band ---------- */
.quote{background:var(--ink);color:#fff}
.quote .wrap{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:0;align-items:center}
.quote-txt{padding:88px 60px 88px 0;min-width:0}
.quote h2{color:#fff;font-size:clamp(30px,3.8vw,46px);margin-bottom:20px}
.quote h2 em{font-style:italic;color:var(--peach)}
.quote p{color:rgba(255,255,255,.76);font-size:16.5px;line-height:1.9;max-width:52ch}
.quote-img{min-width:0;position:relative}
.quote-img img{display:block;width:100%;height:100%;min-height:400px;object-fit:cover}

/* ---------- steps ---------- */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;
  border-top:1px solid var(--line)}
.step{min-width:0;padding:42px 32px 42px 0;border-right:1px solid var(--line);padding-right:32px}
.step:last-child{border-right:0}
.step .n{font-family:var(--serif);font-size:34px;color:var(--peach);display:block;margin-bottom:12px;line-height:1}
.step h3{font-size:21px;margin-bottom:10px}
.step p{font-size:14px;color:var(--muted);line-height:1.75}

/* ---------- enquiry (4-step, pure CSS) ---------- */
.enq{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,.7fr);gap:0;
  background:var(--white);border:1px solid var(--line)}
.enq-main{padding:52px 50px;min-width:0}
.enq-side{background:var(--peach-l);border-left:1px solid var(--line);padding:52px 38px;min-width:0}
.enq-side h3{font-size:23px;margin-bottom:16px}
.enq-side ul{display:grid;gap:14px;margin-bottom:30px}
.enq-side li{display:flex;gap:11px;font-size:13.6px;color:var(--muted);line-height:1.7;min-width:0}
.enq-side li svg{width:16px;height:16px;flex-shrink:0;margin-top:5px}
.mem{background:var(--ink);color:rgba(255,255,255,.8);padding:26px 28px}
.mem .eyebrow{color:rgba(255,255,255,.5);margin-bottom:10px}
.mem h4{font-family:var(--serif);font-size:21px;color:#fff;margin-bottom:12px}
.mem p{font-size:13.2px;line-height:1.75}
.stp{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.stepper{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:34px}
.stepper label{display:flex;align-items:center;gap:10px;min-width:0;cursor:pointer;padding-top:14px;
  border-top:2px solid var(--line);transition:border-color .25s ease}
.stepper b{font-family:var(--serif);font-size:15px;color:var(--muted);flex-shrink:0;transition:color .25s ease}
.stepper span{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);
  font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .25s ease}
.pane{display:none;gap:20px}
#ck1:checked ~ .panes .p1,#ck2:checked ~ .panes .p2,
#ck3:checked ~ .panes .p3,#ck4:checked ~ .panes .p4{display:grid}
#ck1:checked ~ .stepper label:nth-child(1),#ck2:checked ~ .stepper label:nth-child(2),
#ck3:checked ~ .stepper label:nth-child(3),#ck4:checked ~ .stepper label:nth-child(4){border-top-color:var(--apricot)}
#ck1:checked ~ .stepper label:nth-child(1) b,#ck1:checked ~ .stepper label:nth-child(1) span,
#ck2:checked ~ .stepper label:nth-child(2) b,#ck2:checked ~ .stepper label:nth-child(2) span,
#ck3:checked ~ .stepper label:nth-child(3) b,#ck3:checked ~ .stepper label:nth-child(3) span,
#ck4:checked ~ .stepper label:nth-child(4) b,#ck4:checked ~ .stepper label:nth-child(4) span{color:var(--apricot-d)}
.field{min-width:0}
.field>label{display:block;font-size:10px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;
  color:var(--muted);margin-bottom:9px}
input,select,textarea{min-width:0;width:100%;border:1px solid var(--oyster);border-radius:var(--r);
  padding:14px 15px;font-size:14.5px;font-family:var(--sans);color:var(--ink);background:var(--porcelain);
  appearance:none;transition:border-color .2s ease,box-shadow .2s ease}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--apricot);
  box-shadow:0 0 0 3px rgba(231,161,127,.22)}
select{background-image:linear-gradient(45deg,transparent 50%,var(--muted) 50%),
  linear-gradient(135deg,var(--muted) 50%,transparent 50%);
  background-position:calc(100% - 20px) 21px,calc(100% - 14px) 21px;
  background-size:6px 6px,6px 6px;background-repeat:no-repeat;padding-right:42px}
textarea{resize:vertical;min-height:100px;line-height:1.6}
input::placeholder,textarea::placeholder{color:#A79BA1;font-size:13.5px}
input[type=file]{padding:11px 14px;font-size:13px}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.frow>*{min-width:0}
.picks{display:flex;flex-wrap:wrap;gap:9px}
.picks label{display:inline-flex;align-items:center;font-size:12.5px;padding:9px 17px;
  border:1px solid var(--oyster);border-radius:var(--r);background:var(--porcelain);cursor:pointer;
  transition:.18s ease}
.picks input{position:absolute;opacity:0;width:0;height:0}
.picks label:hover{border-color:var(--apricot)}
.picks label:has(input:checked){background:var(--apricot);border-color:var(--apricot);color:var(--ink)}
.picks.tight label{padding:8px 15px;font-size:12px}
.btnrow{display:flex;gap:12px;flex-wrap:wrap}
.btnrow>*{flex:1 1 0;min-width:0}
.btnrow .btn-2{flex:0 0 auto;padding-left:26px;padding-right:26px}
.nextb{cursor:pointer}
.consent{display:flex;gap:12px;align-items:flex-start;font-size:12.8px;color:var(--muted);
  line-height:1.65;cursor:pointer;min-width:0}
.consent input{width:17px;height:17px;flex-shrink:0;margin-top:3px;accent-color:var(--apricot-d);appearance:auto}
.fnote{font-size:11.2px;color:var(--muted);line-height:1.7;text-align:center}
.opt-lbl{font-size:9px;letter-spacing:.14em;color:var(--apricot-d);background:var(--peach-l);
  padding:3px 8px;border-radius:var(--r);margin-left:7px}

/* ---------- planning ---------- */
.plan{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border:1px solid var(--line);
  background:var(--white)}
.plan a{min-width:0;padding:38px 32px;border-right:1px solid var(--line);transition:background .22s ease}
.plan a:last-child{border-right:0}
.plan a:hover{background:var(--peach-l)}
.plan h3{font-size:21px;margin-bottom:10px}
.plan p{font-size:13.4px;color:var(--muted);line-height:1.7}
.plan .lnk{margin-top:16px}

/* ---------- locations ---------- */
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:34px}
.loc-col{min-width:0}
.loc-col h3{font-size:20px;margin-bottom:4px}
.loc-col .st{font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);
  display:block;margin-bottom:14px}
.loc-col li{border-bottom:1px solid var(--line)}
.loc-col a{display:block;font-size:13.8px;padding:9px 0;overflow-wrap:anywhere;transition:.18s ease}
.loc-col a:hover{color:var(--apricot-d);padding-left:6px}
.pop{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
.pop a{border:1px solid var(--line);padding:9px 18px;font-size:12.6px;background:var(--white);
  border-radius:var(--r);transition:.18s ease}
.pop a:hover{border-color:var(--apricot);color:var(--apricot-d)}

/* ---------- faq ---------- */
.faq{max-width:900px;margin:0 auto;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{cursor:pointer;list-style:none;padding:26px 58px 26px 0;position:relative;
  font-family:var(--serif);font-size:22px;transition:color .2s ease}
.faq summary:hover{color:var(--apricot-d)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after,.faq summary::before{content:"";position:absolute;right:12px;top:38px;
  background:var(--apricot-d);transition:transform .25s ease,opacity .25s ease}
.faq summary::after{width:15px;height:1px}
.faq summary::before{width:1px;height:15px;right:19px;top:31px}
.faq details[open] summary::before{opacity:0;transform:rotate(90deg)}
.faq .ans{padding:0 60px 28px 0;font-size:15px;color:var(--muted);line-height:1.9}

/* ---------- final CTA ---------- */
.band{background:var(--ink);color:#fff}
.band .wrap{display:flex;flex-wrap:wrap;gap:26px;align-items:center;justify-content:space-between;
  padding-top:62px;padding-bottom:62px}
.band h2{color:#fff;font-size:clamp(26px,3.4vw,40px);letter-spacing:.02em;min-width:0}
.band h2 em{font-style:italic;color:var(--peach)}
.band p{color:rgba(255,255,255,.72);font-size:14.5px;margin-top:10px}

/* ---------- footer ---------- */
footer{background:var(--ink-d);color:#A79BA1;padding-top:84px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px;
  padding-bottom:54px;border-bottom:1px solid rgba(255,255,255,.12)}
.f-brand{min-width:0}
.f-brand .brand{color:#fff;display:inline-block;margin-bottom:16px}
.f-brand .tag{font-family:var(--serif);font-style:italic;font-size:19px;color:var(--peach);
  display:block;margin-bottom:16px}
.f-brand p{font-size:13.6px;line-height:1.8;max-width:34ch;margin-bottom:22px}
.f-col{min-width:0}
.f-col h3{font-family:var(--sans);font-weight:600;font-size:9.5px;letter-spacing:.22em;
  text-transform:uppercase;color:#fff;margin-bottom:18px}
.f-col li{margin-bottom:11px}
.f-col a{font-size:13.4px;overflow-wrap:anywhere;transition:.18s ease}
.f-col a:hover{color:var(--peach)}
.f-seo{padding:26px 0;border-bottom:1px solid rgba(255,255,255,.12);font-family:var(--serif);
  font-size:19px;color:#fff;text-align:center}
.f-bot{display:flex;flex-wrap:wrap;gap:16px 30px;align-items:center;justify-content:space-between;
  padding:26px 0 32px;font-size:12.2px;color:#847A80}
.f-bot a:hover{color:var(--peach)}
.credit{display:inline-flex;align-items:center;gap:9px;white-space:nowrap}
.credit img{width:22px;height:22px;border-radius:5px;flex-shrink:0;display:block}
.f-bar{background:var(--peach);color:var(--ink);text-align:center;padding:15px 20px;
  font-family:var(--sans);font-size:10.5px;letter-spacing:.24em;text-transform:uppercase;font-weight:600}

/* ---------- sticky mobile ---------- */
.sticky{display:none}

/* ---------- thank you ---------- */
.ty{max-width:720px;margin:0 auto;text-align:center}
.ty-mark{width:76px;height:76px;border:1px solid var(--peach);border-radius:50%;display:grid;
  place-items:center;margin:0 auto 28px}
.ty-mark svg{width:32px;height:32px}
.ty h1{font-size:clamp(34px,4.6vw,52px);margin-bottom:20px;color:var(--ink)}
.ty>.lead{margin:0 auto 38px}
.ty-next{border-top:1px solid var(--line);text-align:left;margin-bottom:38px}
.ty-next li{display:flex;gap:22px;padding:26px 0;border-bottom:1px solid var(--line);min-width:0}
.ty-next b{font-family:var(--serif);font-size:24px;color:var(--peach);flex-shrink:0;line-height:1.1}
.ty-next span{display:block;min-width:0}
.ty-next strong{display:block;font-family:var(--serif);font-weight:400;font-size:21px;
  color:var(--ink);margin-bottom:5px}
.ty-next em{font-style:normal;font-size:14.2px;color:var(--muted);line-height:1.75}
.note{margin-top:34px;font-size:12px;color:var(--muted);border:1px dashed var(--oyster);
  padding:16px 22px;line-height:1.75}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}

/* ================= responsive ================= */
@media (max-width:1500px){ .nav a.top,.nav .drop-lbl{padding:10px 9px;font-size:10.2px;letter-spacing:.11em}
  .hdr{gap:16px} }
@media (max-width:1320px){
  .burger{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--oyster);
    background:var(--white);cursor:pointer;margin-left:auto;flex-shrink:0;border-radius:var(--r)}
  .burger span{display:block;width:20px;height:1px;background:var(--ink);position:relative}
  .burger span::before,.burger span::after{content:"";position:absolute;left:0;width:20px;height:1px;background:var(--ink)}
  .burger span::before{top:-6px}.burger span::after{top:6px}
  .hdr-act{display:none}
  .nav{position:fixed;top:86px;left:0;right:0;bottom:0;margin:0;background:var(--porcelain);
    display:block;overflow-y:auto;padding:22px var(--gut) 48px;clip-path:inset(0 0 0 100%);
    pointer-events:none;opacity:0;transition:clip-path .34s ease,opacity .28s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:18px 2px;font-size:12px;letter-spacing:.16em;justify-content:space-between}
  .nav .caret{width:11px;height:11px;transition:transform .22s ease}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    padding:0 0 16px;min-width:0;max-height:0;overflow:hidden;transition:max-height .34s ease;background:transparent}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 0;font-size:16px;color:var(--muted)}
  .menu .mh{padding-left:0}
  .nav-cta{display:flex!important;flex-direction:column;gap:12px;padding-top:26px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid,.quote .wrap{grid-template-columns:minmax(0,1fr)}
  .hero-txt{padding:64px 0 56px}
  .hero-img img{min-height:400px}
  .quote-txt{padding:64px 0 40px}
  .quote-img img{min-height:300px}
  .t4,.t3{grid-template-columns:repeat(2,minmax(0,1fr))}
  .steps,.plan{grid-template-columns:repeat(2,minmax(0,1fr))}
  .step{border-right:0;border-bottom:1px solid var(--line);padding:34px 0}
  .step:nth-child(odd){border-right:1px solid var(--line);padding-right:28px}
  .step:nth-child(even){padding-left:28px}
  .plan a{border-right:0;border-bottom:1px solid var(--line)}
  .plan a:nth-child(odd){border-right:1px solid var(--line)}
  .enq{grid-template-columns:minmax(0,1fr)}
  .enq-main{padding:40px 32px}
  .enq-side{border-left:0;border-top:1px solid var(--line);padding:40px 32px}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
  .strip .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
}
@media (max-width:768px){
  :root{--gut:24px}
  .sec{padding-top:66px;padding-bottom:66px}
  .sec-t{padding-top:52px;padding-bottom:52px}
  .nav{top:74px}
  .hdr{min-height:74px}
  .brand{font-size:17px;letter-spacing:.12em}
  .stepper span{display:none}
  .stepper label{justify-content:center;padding-top:12px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:11px;
    background:rgba(255,249,243,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);
    padding:11px 16px calc(11px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:15px 10px;font-size:10px;letter-spacing:.1em}
  footer{padding-bottom:80px}
}
@media (max-width:620px){
  .t4,.t3,.t2,.steps,.plan,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .step,.step:nth-child(odd),.step:nth-child(even){border-right:0;padding-left:0;padding-right:0}
  .plan a,.plan a:nth-child(odd){border-right:0}
  .strip .wrap{grid-template-columns:minmax(0,1fr);gap:15px}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:30px}
}
@media (max-width:430px){
  :root{--gut:18px}
  .enq-main,.enq-side{padding:30px 20px}
  .tile .tb{padding:18px}
  .btn{white-space:normal;text-align:center;padding-left:22px;padding-right:22px;max-width:100%}
  .btnrow{flex-direction:column}
  .btnrow>*{width:100%}
  .faq summary{font-size:19px;padding-right:44px}
}

:root{
  --porcelain:#FFF9F3; --apricot:#E7A17F; --apricot-d:#D08761; --peach:#F2C5B2;
  --peach-l:#FBEDE5; --gold:#C2A05C; --ink:#3D303B; --ink-d:#2C222B; --oyster:#DDD4CC;
  --muted:#7A6E76; --line:#EADFD6; --white:#FFFFFF;
  --gut:44px; --r:2px;
  --shadow:0 1px 2px rgba(61,48,59,.04), 0 12px 32px rgba(61,48,59,.07);
  --shadow-lg:0 2px 6px rgba(61,48,59,.05), 0 28px 66px rgba(61,48,59,.12);
  --serif:"Cormorant Garamond",Georgia,"Times New Roman",serif;
  --sans:Montserrat,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--porcelain);color:var(--ink);font-family:var(--sans);
  font-size:16px;line-height:1.75;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--serif);font-weight:400;line-height:1.16;letter-spacing:0;margin:0}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul,ol{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:1300px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:104px;padding-bottom:104px}
.sec-t{padding-top:74px;padding-bottom:74px}
.eyebrow{font-family:var(--sans);font-weight:500;font-size:11px;letter-spacing:.24em;
  text-transform:uppercase;color:var(--muted);margin-bottom:18px}
.h2{font-size:clamp(31px,4.1vw,50px)}
.lead{color:var(--muted);font-size:16.5px;max-width:60ch;line-height:1.85}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.sec-head{margin-bottom:48px}
em.acc{font-style:italic;color:var(--apricot-d)}
.gold-rule{width:46px;height:1px;background:var(--gold);margin:0 0 22px}
.ctr .gold-rule{margin-left:auto;margin-right:auto}

/* ---------- images ---------- */
.cimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:var(--peach-l)}
.simg{display:block;width:100%;height:auto;aspect-ratio:4/5;object-fit:cover;background:var(--peach-l)}

/* ---------- reveal (pure CSS, JS-free) ---------- */
.rv{animation:rvIn .9s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:.55;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:var(--sans);font-weight:600;font-size:11.5px;letter-spacing:.18em;text-transform:uppercase;
  padding:18px 36px;border-radius:var(--r);border:1px solid transparent;cursor:pointer;
  transition:background .22s ease,color .22s ease,border-color .22s ease;white-space:nowrap}
.btn-1{background:var(--apricot);color:var(--ink)}
.btn-1:hover{background:var(--apricot-d);color:#fff}
.btn-2{background:transparent;color:var(--ink);border-color:var(--oyster)}
.btn-2:hover{border-color:var(--apricot);background:var(--peach-l)}
.btn-d{background:var(--ink);color:#fff}
.btn-d:hover{background:var(--ink-d)}
.btn-w{background:#fff;color:var(--ink);border-color:#fff}
.btn-w:hover{background:var(--peach-l)}
.btn-o{background:transparent;color:#fff;border-color:rgba(255,255,255,.48)}
.btn-o:hover{background:rgba(255,255,255,.13);border-color:#fff}
.btn-sm{padding:13px 24px;font-size:10.5px}
.btn-lg{padding:20px 44px;font-size:12px}
.lnk{font-family:var(--sans);font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;
  font-weight:600;color:var(--apricot-d);display:inline-flex;align-items:center;gap:9px}
.lnk::after{content:"";width:20px;height:1px;background:var(--apricot-d);transition:width .22s ease}
a:hover .lnk::after{width:32px}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(255,249,243,.96);
  backdrop-filter:saturate(150%) blur(12px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:24px;min-height:86px}
.brand{flex-shrink:0;font-family:var(--serif);font-size:21px;letter-spacing:.16em;color:var(--ink);
  white-space:nowrap;line-height:1;text-transform:uppercase}
.nav{margin-left:auto;display:flex;align-items:center;gap:2px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:6px;padding:10px 12px;
  font-size:10.8px;letter-spacing:.15em;text-transform:uppercase;font-weight:600;color:var(--ink);
  cursor:pointer;white-space:nowrap;transition:color .2s ease}
.nav a.top:hover,.nav .drop-lbl:hover{color:var(--apricot-d)}
.nav-cta{display:none}
.nav .caret{width:8px;height:8px;flex-shrink:0;opacity:.55}
.menu{position:absolute;top:calc(100% + 16px);left:-10px;min-width:264px;background:var(--white);
  border:1px solid var(--line);box-shadow:var(--shadow-lg);padding:16px 12px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.2s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:9px 14px;font-size:15px;font-family:var(--serif);color:var(--ink);
  transition:.18s ease}
.menu a:hover{background:var(--peach-l);color:var(--apricot-d)}
.menu .mh{display:block;padding:4px 14px 10px;font-size:9.5px;letter-spacing:.22em;
  text-transform:uppercase;color:var(--muted);font-family:var(--sans);font-weight:600}
.hdr-act{display:flex;align-items:center;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- hero ---------- */
.hero{background:var(--peach-l);border-bottom:1px solid var(--line)}
.hero-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.02fr);gap:0;align-items:stretch}
.hero-txt{padding:98px 64px 98px 0;display:flex;flex-direction:column;justify-content:center;min-width:0}
h1{font-size:clamp(36px,4.7vw,58px);margin-bottom:22px;line-height:1.12}
h1 em{font-style:italic;color:var(--apricot-d)}
.hero-lead{font-size:16.5px;color:var(--muted);max-width:48ch;margin-bottom:34px;line-height:1.85}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:34px}
.ticks{display:flex;flex-wrap:wrap;gap:12px 28px}
.tick{display:flex;align-items:center;gap:9px;font-size:12.5px;color:var(--muted);letter-spacing:.03em}
.tick svg{width:15px;height:15px;flex-shrink:0}
.hero-img{position:relative;min-width:0}
.hero-img img{display:block;width:100%;height:100%;min-height:560px;object-fit:cover}
.swap-tag{position:absolute;right:14px;bottom:14px;background:rgba(61,48,59,.62);color:#fff;
  font-size:9.5px;letter-spacing:.14em;text-transform:uppercase;padding:7px 14px;border-radius:var(--r)}

/* ---------- trust strip ---------- */
.strip{background:var(--ink);color:#E8E1E4}
.strip .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;
  padding-top:28px;padding-bottom:28px}
.strip div{min-width:0;display:flex;align-items:center;gap:12px;font-size:12.6px;letter-spacing:.04em}
.strip svg{width:18px;height:18px;flex-shrink:0}

/* ---------- tiles ---------- */
.tiles{display:grid;gap:24px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tile{min-width:0;display:block;background:var(--white);border:1px solid var(--line);
  transition:border-color .25s ease,box-shadow .25s ease}
.tile:hover{border-color:var(--peach);box-shadow:var(--shadow)}
.tile .tb{padding:20px 22px 24px}
.tile b{display:block;font-family:var(--serif);font-weight:400;font-size:21px;margin-bottom:5px}
.tile span{display:block;font-size:13px;color:var(--muted);line-height:1.7}
.tile .lnk{margin-top:14px}
.kwl{margin-top:12px;font-size:11.5px;color:var(--muted);line-height:1.75}
.kwl b{display:inline;font-family:var(--sans);font-size:11.5px;font-weight:600;color:var(--ink)}

/* ---------- dark quote band ---------- */
.quote{background:var(--ink);color:#fff}
.quote .wrap{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:0;align-items:center}
.quote-txt{padding:88px 60px 88px 0;min-width:0}
.quote h2{color:#fff;font-size:clamp(30px,3.8vw,46px);margin-bottom:20px}
.quote h2 em{font-style:italic;color:var(--peach)}
.quote p{color:rgba(255,255,255,.76);font-size:16.5px;line-height:1.9;max-width:52ch}
.quote-img{min-width:0;position:relative}
.quote-img img{display:block;width:100%;height:100%;min-height:400px;object-fit:cover}

/* ---------- steps ---------- */
.steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;
  border-top:1px solid var(--line)}
.step{min-width:0;padding:42px 32px 42px 0;border-right:1px solid var(--line);padding-right:32px}
.step:last-child{border-right:0}
.step .n{font-family:var(--serif);font-size:34px;color:var(--peach);display:block;margin-bottom:12px;line-height:1}
.step h3{font-size:21px;margin-bottom:10px}
.step p{font-size:14px;color:var(--muted);line-height:1.75}

/* ---------- enquiry (4-step, pure CSS) ---------- */
.enq{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,.7fr);gap:0;
  background:var(--white);border:1px solid var(--line)}
.enq-main{padding:52px 50px;min-width:0}
.enq-side{background:var(--peach-l);border-left:1px solid var(--line);padding:52px 38px;min-width:0}
.enq-side h3{font-size:23px;margin-bottom:16px}
.enq-side ul{display:grid;gap:14px;margin-bottom:30px}
.enq-side li{display:flex;gap:11px;font-size:13.6px;color:var(--muted);line-height:1.7;min-width:0}
.enq-side li svg{width:16px;height:16px;flex-shrink:0;margin-top:5px}
.mem{background:var(--ink);color:rgba(255,255,255,.8);padding:26px 28px}
.mem .eyebrow{color:rgba(255,255,255,.5);margin-bottom:10px}
.mem h4{font-family:var(--serif);font-size:21px;color:#fff;margin-bottom:12px}
.mem p{font-size:13.2px;line-height:1.75}
.stp{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.stepper{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:34px}
.stepper label{display:flex;align-items:center;gap:10px;min-width:0;cursor:pointer;padding-top:14px;
  border-top:2px solid var(--line);transition:border-color .25s ease}
.stepper b{font-family:var(--serif);font-size:15px;color:var(--muted);flex-shrink:0;transition:color .25s ease}
.stepper span{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);
  font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .25s ease}
.pane{display:none;gap:20px}
#ck1:checked ~ .panes .p1,#ck2:checked ~ .panes .p2,
#ck3:checked ~ .panes .p3,#ck4:checked ~ .panes .p4{display:grid}
#ck1:checked ~ .stepper label:nth-child(1),#ck2:checked ~ .stepper label:nth-child(2),
#ck3:checked ~ .stepper label:nth-child(3),#ck4:checked ~ .stepper label:nth-child(4){border-top-color:var(--apricot)}
#ck1:checked ~ .stepper label:nth-child(1) b,#ck1:checked ~ .stepper label:nth-child(1) span,
#ck2:checked ~ .stepper label:nth-child(2) b,#ck2:checked ~ .stepper label:nth-child(2) span,
#ck3:checked ~ .stepper label:nth-child(3) b,#ck3:checked ~ .stepper label:nth-child(3) span,
#ck4:checked ~ .stepper label:nth-child(4) b,#ck4:checked ~ .stepper label:nth-child(4) span{color:var(--apricot-d)}
.field{min-width:0}
.field>label{display:block;font-size:10px;font-weight:600;letter-spacing:.2em;text-transform:uppercase;
  color:var(--muted);margin-bottom:9px}
input,select,textarea{min-width:0;width:100%;border:1px solid var(--oyster);border-radius:var(--r);
  padding:14px 15px;font-size:14.5px;font-family:var(--sans);color:var(--ink);background:var(--porcelain);
  appearance:none;transition:border-color .2s ease,box-shadow .2s ease}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--apricot);
  box-shadow:0 0 0 3px rgba(231,161,127,.22)}
select{background-image:linear-gradient(45deg,transparent 50%,var(--muted) 50%),
  linear-gradient(135deg,var(--muted) 50%,transparent 50%);
  background-position:calc(100% - 20px) 21px,calc(100% - 14px) 21px;
  background-size:6px 6px,6px 6px;background-repeat:no-repeat;padding-right:42px}
textarea{resize:vertical;min-height:100px;line-height:1.6}
input::placeholder,textarea::placeholder{color:#A79BA1;font-size:13.5px}
input[type=file]{padding:11px 14px;font-size:13px}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.frow>*{min-width:0}
.picks{display:flex;flex-wrap:wrap;gap:9px}
.picks label{display:inline-flex;align-items:center;font-size:12.5px;padding:9px 17px;
  border:1px solid var(--oyster);border-radius:var(--r);background:var(--porcelain);cursor:pointer;
  transition:.18s ease}
.picks input{position:absolute;opacity:0;width:0;height:0}
.picks label:hover{border-color:var(--apricot)}
.picks label:has(input:checked){background:var(--apricot);border-color:var(--apricot);color:var(--ink)}
.picks.tight label{padding:8px 15px;font-size:12px}
.btnrow{display:flex;gap:12px;flex-wrap:wrap}
.btnrow>*{flex:1 1 0;min-width:0}
.btnrow .btn-2{flex:0 0 auto;padding-left:26px;padding-right:26px}
.nextb{cursor:pointer}
.consent{display:flex;gap:12px;align-items:flex-start;font-size:12.8px;color:var(--muted);
  line-height:1.65;cursor:pointer;min-width:0}
.consent input{width:17px;height:17px;flex-shrink:0;margin-top:3px;accent-color:var(--apricot-d);appearance:auto}
.fnote{font-size:11.2px;color:var(--muted);line-height:1.7;text-align:center}
.opt-lbl{font-size:9px;letter-spacing:.14em;color:var(--apricot-d);background:var(--peach-l);
  padding:3px 8px;border-radius:var(--r);margin-left:7px}

/* ---------- planning ---------- */
.plan{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;border:1px solid var(--line);
  background:var(--white)}
.plan a{min-width:0;padding:38px 32px;border-right:1px solid var(--line);transition:background .22s ease}
.plan a:last-child{border-right:0}
.plan a:hover{background:var(--peach-l)}
.plan h3{font-size:21px;margin-bottom:10px}
.plan p{font-size:13.4px;color:var(--muted);line-height:1.7}
.plan .lnk{margin-top:16px}

/* ---------- locations ---------- */
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:34px}
.loc-col{min-width:0}
.loc-col h3{font-size:20px;margin-bottom:4px}
.loc-col .st{font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);
  display:block;margin-bottom:14px}
.loc-col li{border-bottom:1px solid var(--line)}
.loc-col a{display:block;font-size:13.8px;padding:9px 0;overflow-wrap:anywhere;transition:.18s ease}
.loc-col a:hover{color:var(--apricot-d);padding-left:6px}
.pop{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
.pop a{border:1px solid var(--line);padding:9px 18px;font-size:12.6px;background:var(--white);
  border-radius:var(--r);transition:.18s ease}
.pop a:hover{border-color:var(--apricot);color:var(--apricot-d)}

/* ---------- faq ---------- */
.faq{max-width:900px;margin:0 auto;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{cursor:pointer;list-style:none;padding:26px 58px 26px 0;position:relative;
  font-family:var(--serif);font-size:22px;transition:color .2s ease}
.faq summary:hover{color:var(--apricot-d)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after,.faq summary::before{content:"";position:absolute;right:12px;top:38px;
  background:var(--apricot-d);transition:transform .25s ease,opacity .25s ease}
.faq summary::after{width:15px;height:1px}
.faq summary::before{width:1px;height:15px;right:19px;top:31px}
.faq details[open] summary::before{opacity:0;transform:rotate(90deg)}
.faq .ans{padding:0 60px 28px 0;font-size:15px;color:var(--muted);line-height:1.9}

/* ---------- final CTA ---------- */
.band{background:var(--ink);color:#fff}
.band .wrap{display:flex;flex-wrap:wrap;gap:26px;align-items:center;justify-content:space-between;
  padding-top:62px;padding-bottom:62px}
.band h2{color:#fff;font-size:clamp(26px,3.4vw,40px);letter-spacing:.02em;min-width:0}
.band h2 em{font-style:italic;color:var(--peach)}
.band p{color:rgba(255,255,255,.72);font-size:14.5px;margin-top:10px}

/* ---------- footer ---------- */
footer{background:var(--ink-d);color:#A79BA1;padding-top:84px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px;
  padding-bottom:54px;border-bottom:1px solid rgba(255,255,255,.12)}
.f-brand{min-width:0}
.f-brand .brand{color:#fff;display:inline-block;margin-bottom:16px}
.f-brand .tag{font-family:var(--serif);font-style:italic;font-size:19px;color:var(--peach);
  display:block;margin-bottom:16px}
.f-brand p{font-size:13.6px;line-height:1.8;max-width:34ch;margin-bottom:22px}
.f-col{min-width:0}
.f-col h3{font-family:var(--sans);font-weight:600;font-size:9.5px;letter-spacing:.22em;
  text-transform:uppercase;color:#fff;margin-bottom:18px}
.f-col li{margin-bottom:11px}
.f-col a{font-size:13.4px;overflow-wrap:anywhere;transition:.18s ease}
.f-col a:hover{color:var(--peach)}
.f-seo{padding:26px 0;border-bottom:1px solid rgba(255,255,255,.12);font-family:var(--serif);
  font-size:19px;color:#fff;text-align:center}
.f-bot{display:flex;flex-wrap:wrap;gap:16px 30px;align-items:center;justify-content:space-between;
  padding:26px 0 32px;font-size:12.2px;color:#847A80}
.f-bot a:hover{color:var(--peach)}
.credit{display:inline-flex;align-items:center;gap:9px;white-space:nowrap}
.credit img{width:22px;height:22px;border-radius:5px;flex-shrink:0;display:block}
.f-bar{background:var(--peach);color:var(--ink);text-align:center;padding:15px 20px;
  font-family:var(--sans);font-size:10.5px;letter-spacing:.24em;text-transform:uppercase;font-weight:600}

/* ---------- sticky mobile ---------- */
.sticky{display:none}

/* ---------- thank you ---------- */
.ty{max-width:720px;margin:0 auto;text-align:center}
.ty-mark{width:76px;height:76px;border:1px solid var(--peach);border-radius:50%;display:grid;
  place-items:center;margin:0 auto 28px}
.ty-mark svg{width:32px;height:32px}
.ty h1{font-size:clamp(34px,4.6vw,52px);margin-bottom:20px;color:var(--ink)}
.ty>.lead{margin:0 auto 38px}
.ty-next{border-top:1px solid var(--line);text-align:left;margin-bottom:38px}
.ty-next li{display:flex;gap:22px;padding:26px 0;border-bottom:1px solid var(--line);min-width:0}
.ty-next b{font-family:var(--serif);font-size:24px;color:var(--peach);flex-shrink:0;line-height:1.1}
.ty-next span{display:block;min-width:0}
.ty-next strong{display:block;font-family:var(--serif);font-weight:400;font-size:21px;
  color:var(--ink);margin-bottom:5px}
.ty-next em{font-style:normal;font-size:14.2px;color:var(--muted);line-height:1.75}
.note{margin-top:34px;font-size:12px;color:var(--muted);border:1px dashed var(--oyster);
  padding:16px 22px;line-height:1.75}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}

/* ================= responsive ================= */
@media (max-width:1500px){ .nav a.top,.nav .drop-lbl{padding:10px 9px;font-size:10.2px;letter-spacing:.11em}
  .hdr{gap:16px} }
@media (max-width:1320px){
  .burger{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--oyster);
    background:var(--white);cursor:pointer;margin-left:auto;flex-shrink:0;border-radius:var(--r)}
  .burger span{display:block;width:20px;height:1px;background:var(--ink);position:relative}
  .burger span::before,.burger span::after{content:"";position:absolute;left:0;width:20px;height:1px;background:var(--ink)}
  .burger span::before{top:-6px}.burger span::after{top:6px}
  .hdr-act{display:none}
  .nav{position:fixed;top:86px;left:0;right:0;bottom:0;margin:0;background:var(--porcelain);
    display:block;overflow-y:auto;padding:22px var(--gut) 48px;clip-path:inset(0 0 0 100%);
    pointer-events:none;opacity:0;transition:clip-path .34s ease,opacity .28s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:18px 2px;font-size:12px;letter-spacing:.16em;justify-content:space-between}
  .nav .caret{width:11px;height:11px;transition:transform .22s ease}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    padding:0 0 16px;min-width:0;max-height:0;overflow:hidden;transition:max-height .34s ease;background:transparent}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 0;font-size:16px;color:var(--muted)}
  .menu .mh{padding-left:0}
  .nav-cta{display:flex!important;flex-direction:column;gap:12px;padding-top:26px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid,.quote .wrap{grid-template-columns:minmax(0,1fr)}
  .hero-txt{padding:64px 0 56px}
  .hero-img img{min-height:400px}
  .quote-txt{padding:64px 0 40px}
  .quote-img img{min-height:300px}
  .t4,.t3{grid-template-columns:repeat(2,minmax(0,1fr))}
  .steps,.plan{grid-template-columns:repeat(2,minmax(0,1fr))}
  .step{border-right:0;border-bottom:1px solid var(--line);padding:34px 0}
  .step:nth-child(odd){border-right:1px solid var(--line);padding-right:28px}
  .step:nth-child(even){padding-left:28px}
  .plan a{border-right:0;border-bottom:1px solid var(--line)}
  .plan a:nth-child(odd){border-right:1px solid var(--line)}
  .enq{grid-template-columns:minmax(0,1fr)}
  .enq-main{padding:40px 32px}
  .enq-side{border-left:0;border-top:1px solid var(--line);padding:40px 32px}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
  .strip .wrap{grid-template-columns:repeat(2,minmax(0,1fr))}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
}
@media (max-width:768px){
  :root{--gut:24px}
  .sec{padding-top:66px;padding-bottom:66px}
  .sec-t{padding-top:52px;padding-bottom:52px}
  .nav{top:74px}
  .hdr{min-height:74px}
  .brand{font-size:17px;letter-spacing:.12em}
  .stepper span{display:none}
  .stepper label{justify-content:center;padding-top:12px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:11px;
    background:rgba(255,249,243,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);
    padding:11px 16px calc(11px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:15px 10px;font-size:10px;letter-spacing:.1em}
  footer{padding-bottom:80px}
}
@media (max-width:620px){
  .t4,.t3,.t2,.steps,.plan,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .step,.step:nth-child(odd),.step:nth-child(even){border-right:0;padding-left:0;padding-right:0}
  .plan a,.plan a:nth-child(odd){border-right:0}
  .strip .wrap{grid-template-columns:minmax(0,1fr);gap:15px}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:30px}
}
@media (max-width:430px){
  :root{--gut:18px}
  .enq-main,.enq-side{padding:30px 20px}
  .tile .tb{padding:18px}
  .btn{white-space:normal;text-align:center;padding-left:22px;padding-right:22px;max-width:100%}
  .btnrow{flex-direction:column}
  .btnrow>*{width:100%}
  .faq summary{font-size:19px;padding-right:44px}
}
